namespace Torii.Api.Models;

/// <summary>
/// File stored on disk (see <c>IFileStorage</c>); only the metadata lives in the database.
/// A file is attached to channels through <see cref="ChannelFile"/> links, so forwarding it
/// to another channel only adds a link (the bytes are never copied).
/// </summary>
public class StoredFile : Entity
{
    /// <summary>Opaque storage key (relative path under <c>Storage:Path</c>), generated by the app.</summary>
    public string StorageKey { get; set; } = null!;

    /// <summary>Original file name, sanitized (no path).</summary>
    public string FileName { get; set; } = null!;

    public string ContentType { get; set; } = null!;

    /// <summary>Size in bytes.</summary>
    public long Size { get; set; }

    public ICollection<ChannelFile> ChannelLinks { get; set; } = [];
}
